local P=C_Spell and C_Spell.GetSpellDisplayCount function P8BA6426E.ResolveChargeDisplaySpellID(P,j)local Y=j or{P}local X=P or Y[1]if C_Spell and C_Spell.GetOverrideSpell then for P,j in ipairs(Y)do local Y,X=pcall(C_Spell.GetOverrideSpell,j,0,true)if Y and(type(X)=="number"and X~=j)then return X end end end if C_SpellBook and C_SpellBook.IsSpellKnown then for P,j in ipairs(Y)do local Y,X=pcall(C_SpellBook.IsSpellKnown,j)if Y and X then return j end end end return X end function P8BA6426E.GetSpellChargeCount(j,Y)if not P then return nil end local X=P8BA6426E.ResolveChargeDisplaySpellID(j,Y)if not X then return nil end local M,z=pcall(P,X)if M then if type(z)=="number"then return z end if type(z)=="string"then local P,j=pcall(tonumber,z)if P and type(j)=="number"then return z end end end return nil end function P8BA6426E.GetSpellChargeDisplayRaw(j,Y)if not P then return false end local X=P8BA6426E.ResolveChargeDisplaySpellID(j,Y)if not X then return false end local M,z=pcall(P,X)if M and type(z)~="nil"then return true,z end return false end